<?php require 'config.php';require_user();
// A full SQL import can recreate users and invalidate an older browser session.
$checkUser=$pdo->prepare('SELECT id FROM users WHERE id=?');
$checkUser->execute([$_SESSION['user_id']]);
if(!$checkUser->fetchColumn()){unset($_SESSION['user_id'],$_SESSION['user_name']);session_regenerate_id(true);flash('Your session is no longer valid. Please log in again or create a new account.','error');go('/MediHome/login.php');}
$cart=$_SESSION['cart']??[];if(!$cart){flash('Your cart is empty.','error');go('/MediHome/cart.php');}$ids=array_map('intval',array_keys($cart));$in=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM medicines WHERE id IN ($in)");$s->execute($ids);$products=$s->fetchAll();$total=0;foreach($products as $p)$total+=(float)$p['price']*min((int)$cart[$p['id']],(int)$p['stock']);$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');$pay='Cash on Delivery';if(!$name||!$phone||!$address)$err='Fill all required fields.';else{try{$pdo->beginTransaction();$s=$pdo->prepare("INSERT INTO orders(user_id,customer_name,phone,address,payment_method,total) VALUES(?,?,?,?,?,?)");$s->execute([$_SESSION['user_id'],$name,$phone,$address,$pay,$total]);$oid=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO order_items(order_id,medicine_id,medicine_name,quantity,unit_price) VALUES(?,?,?,?,?)');$upd=$pdo->prepare('UPDATE medicines SET stock=stock-? WHERE id=? AND stock>=?');foreach($products as $p){$qty=min((int)$cart[$p['id']],(int)$p['stock']);if($qty<1)throw new RuntimeException('Stock changed. Please review your cart.');$upd->execute([$qty,$p['id'],$qty]);if(!$upd->rowCount())throw new RuntimeException('Insufficient stock. Please review your cart.');$ins->execute([$oid,$p['id'],$p['name'],$qty,$p['price']]);}$pdo->commit();unset($_SESSION['cart']);flash('Order placed successfully.');go('/MediHome/orders.php?id='.$oid);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e instanceof RuntimeException?$e->getMessage():'Could not place order. Try again.';}}}$title='Checkout | MediHome';require 'includes/header.php';?><div class="pagehead"><span class="eyebrow">Checkout</span><h1>Delivery details</h1><p>Choose your preferred payment option and confirm your order.</p></div><?php if($err):?><div class="flash error"><?=e($err)?></div><?php endif;?><div class="detailgrid"><div class="formbox"><form method="post"><div class="field"><label>Full name</label><input class="input" name="name" required></div><div class="field"><label>Phone</label><input class="input" name="phone" required></div><div class="field"><label>Delivery address</label><textarea name="address" rows="4" required></textarea></div><div class="field"><label>Payment method</label><div class="cod-choice"><span class="cod-icon">💵</span><span><strong>Cash on Delivery (COD)</strong><small>Pay in cash when your order is delivered.</small></span><b>✓ Selected</b></div></div><div class="notice">Cash on Delivery is the only available payment method. Please verify your delivery details before placing the order.</div><button class="btn">Place order · <?=money($total)?></button></form></div><div class="detail"><h2>Order summary</h2><?php foreach($products as $p):?><p><?=e($p['name'])?> × <?= (int)$cart[$p['id']]?> — <strong><?=money($p['price']*(int)$cart[$p['id']])?></strong></p><?php endforeach;?><h2><?=money($total)?></h2></div></div><?php require 'includes/footer.php';?>